import "server-only";

import { z } from "zod";
import { AppError } from "@/lib/errors";

export class BillingError extends AppError {
  retryAfter?: number;
  constructor(
    readonly code: string,
    message = "Billing is temporarily unavailable.",
    readonly status = 503,
  ) {
    super(message);
  }
}

// Require an explicit mode. Never infer live mode from a key or SDK default.
export function billingConfig(
  env: Record<string, string | undefined> = process.env,
) {
  const parsed = z
    .object({
      DODO_PAYMENTS_ENVIRONMENT: z.enum(["test_mode", "live_mode"]),
      DODO_PAYMENTS_API_KEY: z.string().trim().min(1),
      DODO_PAID_MONTHLY_PRODUCT_ID: z.string().trim().min(1),
      DODO_PAYMENTS_WEBHOOK_KEY: z.string().trim().min(1),
      DODO_PAYMENTS_BUSINESS_ID: z.string().trim().min(1),
    })
    .safeParse(env);
  if (
    !parsed.success ||
    env.DODO_PAYMENTS_BASE_URL ||
    env.DODO_PAYMENTS_CUSTOM_HEADERS
  )
    throw new BillingError("BILLING_CONFIGURATION");
  let origin: URL;
  try {
    origin = new URL(env.APP_ORIGIN || env.AUTH_URL || "");
  } catch {
    throw new BillingError("BILLING_CONFIGURATION");
  }
  if (
    origin.username ||
    origin.password ||
    origin.search ||
    origin.hash ||
    origin.pathname !== "/" ||
    !(
      origin.protocol === "https:" ||
      (origin.protocol === "http:" &&
        ["localhost", "127.0.0.1", "[::1]"].includes(origin.hostname))
    )
  )
    throw new BillingError("BILLING_CONFIGURATION");
  if (
    parsed.data.DODO_PAYMENTS_ENVIRONMENT === "live_mode" &&
    origin.protocol !== "https:"
  )
    throw new BillingError("BILLING_CONFIGURATION");
  return {
    environment: parsed.data.DODO_PAYMENTS_ENVIRONMENT,
    apiKey: parsed.data.DODO_PAYMENTS_API_KEY,
    productId: parsed.data.DODO_PAID_MONTHLY_PRODUCT_ID,
    webhookKey: parsed.data.DODO_PAYMENTS_WEBHOOK_KEY,
    businessId: parsed.data.DODO_PAYMENTS_BUSINESS_ID,
    origin: origin.origin,
  };
}

export { BILLING_PRICES } from "@/lib/pricing";
